Counter(v for _,_,v in sources),sources

dist={}; labels=defaultdict(set); q=deque()
for r,c,v in sources:
 if (r,c) not in dist: dist[(r,c)]=0; labels[(r,c)]={v}; q.append((r,c))
 else: labels[(r,c)].add(v)
